func main() {
	ctx := context.Background()

	mux := runtime.NewServeMux()
	opts := []grpc.DialOption{
		grpc.WithTransportCredentials(insecure.NewCredentials()),
	}

	if err := pb.RegisterOrdersHandlerFromEndpoint(ctx, mux, "orders:50051", opts); err != nil {
		log.Fatal(err)
	}
	if err := pb.RegisterPaymentsHandlerFromEndpoint(ctx, mux, "payments:50051", opts); err != nil {
		log.Fatal(err)
	}

	log.Printf("public gateway listening on :8080")
	log.Fatal(http.ListenAndServe(":8080", mux))
}
